#!/usr/bin/env bash
# Patches the manifest generated by `flutter create` with everything the
# MovieBox shell needs (permissions, download service, FileProvider, PiP).
# Usage: android-app/patch-manifest.sh app/android/app/src/main/AndroidManifest.xml
set -euo pipefail

M="${1:?usage: patch-manifest.sh path/to/AndroidManifest.xml}"
[ -f "$M" ] || { echo "manifest not found: $M" >&2; exit 1; }

# Cleartext is needed for the embedded 127.0.0.1 server.
if ! grep -q 'usesCleartextTraffic' "$M"; then
  sed -i 's#<application#<application android:usesCleartextTraffic="true"#' "$M"
fi
sed -i 's#android:label="moviebox"#android:label="MovieBox Web"#' "$M"
if ! grep -q 'android:roundIcon' "$M"; then
  sed -i 's#android:icon="@mipmap/ic_launcher"#android:icon="@mipmap/ic_launcher" android:roundIcon="@mipmap/ic_launcher_round"#' "$M"
fi

# Permissions.
if ! grep -q 'android.permission.INTERNET' "$M"; then
  sed -i '/<manifest /a\
    <uses-permission android:name="android.permission.INTERNET"/>' "$M"
fi
if ! grep -q 'POST_NOTIFICATIONS' "$M"; then
  sed -i '/<manifest /a\
    <uses-permission android:name="android.permission.POST_NOTIFICATIONS"/>\
    <uses-permission android:name="android.permission.FOREGROUND_SERVICE"/>\
    <uses-permission android:name="android.permission.FOREGROUND_SERVICE_DATA_SYNC"/>\
    <uses-permission android:name="android.permission.MODIFY_AUDIO_SETTINGS"/>\
    <uses-permission android:name="android.permission.WAKE_LOCK"/>' "$M"
fi

# Picture-in-Picture on the Flutter activity.
if ! grep -q 'supportsPictureInPicture' "$M"; then
  sed -i 's#android:name=".MainActivity"#android:name=".MainActivity"\n            android:supportsPictureInPicture="true"#' "$M"
fi

# Download service + media-button receiver + FileProvider for legacy downloads.
if ! grep -q 'DownloadService' "$M"; then
  sed -i 's#</application>#        <service android:name=".DownloadService"\n            android:exported="false"\n            android:foregroundServiceType="dataSync"/>\n        <receiver android:name=".MediaActionReceiver" android:exported="false"/>\n        <provider\n            android:name="androidx.core.content.FileProvider"\n            android:authorities="${applicationId}.fileprovider"\n            android:exported="false"\n            android:grantUriPermissions="true">\n            <meta-data android:name="android.support.FILE_PROVIDER_PATHS" android:resource="@xml/file_paths"/>\n        </provider>\n    </application>#' "$M"
fi

echo "Patched $M"
